(() => {
 const F=globalThis.LuminaOrderFormat,locale=document.documentElement.lang;
 const orderBadge=o=>`<span class="admin-badge state-${e(F.displayStatus(o))}">${e(stateLabel(F.displayStatus(o)))}</span>`;
 const shell=document.querySelector('[data-admin]');if(!shell)return;
 const fr=document.documentElement.lang.startsWith('fr'),L=(en,frText)=>fr?frText:en,$=s=>shell.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=c=>new Intl.NumberFormat(fr?'fr-CA':'en-CA',{style:'currency',currency:'CAD'}).format((c||0)/100),status=$('[data-admin-status]'),content=$('[data-admin-content]');let csrf='',offset=0;

 const stateLabel=s=>({pending_payment:L('Pending payment','En attente de paiement'),awaiting_verification:L('Awaiting verification','En attente de vérification'),paid:L('Paid','Payé'),refunded:L('Refunded','Remboursé'),processing:L('Processing','En traitement'),fulfilled:L('Fulfilled','Activé'),cancelled:L('Cancelled','Annulé'),active:L('Active','Actif'),expired:L('Expired','Expiré'),pending:L('Pending','En attente'),verified:L('Verified','Vérifié'),rejected:L('Rejected','Rejeté'),draft:L('Draft / non-fiscal','Brouillon / non fiscal'),issued:L('Issued','Émise'),credited:L('Credited','Créditée'),proforma:L('Pro forma','Pro forma'),final:L('Final invoice','Facture définitive'),credit:L('Credit note','Note de crédit'),test:L('Demo / test','Démo / test'),live:L('Live mode','Mode réel')})[s]||s;
 async function api(path,data,extra={}){const response=await fetch('/api/admin/'+path,{method:data===undefined?'GET':'POST',cache:'no-store',headers:{'Content-Type':'application/json','X-Lumina-Request':'1','X-CSRF-Token':csrf,...extra},...(data===undefined?{}:{body:JSON.stringify(data)})});const result=await response.json();if(!response.ok)throw Error(result.error);return result;}
 const message=error=>status.textContent=error.message||error;
 const safeAction=fn=>async event=>{event?.preventDefault();status.textContent='';const button=event?.submitter||event?.currentTarget;if(button?.tagName==='BUTTON')button.disabled=true;try{await fn(event);}catch(error){message(error);const inline=event?.target?.querySelector?.('[data-action-error]');if(inline){inline.textContent=error.message||error;inline.setAttribute('role','alert');inline.scrollIntoView({block:'nearest'});}}finally{if(button?.tagName==='BUTTON')button.disabled=false;}};
 const invoiceLink=i=>`<a class="btn small" href="/api/admin/invoices/${i.id}/pdf">${e(i.number||i.id)} PDF</a>`;
 const orderLink=o=>`<button class="btn small" data-open-order="${e(o.public_id)}">${e(o.reference||o.public_id.slice(0,10))}</button>`;
 function wireOrders(){content.querySelectorAll('[data-open-order]').forEach(b=>b.addEventListener('click',safeAction(()=>detail(b.dataset.openOrder))));}
 function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
 async function detail(id){const o=await api('orders/'+id);content.innerHTML=`<div class="commerce-box"><h2>${e(o.reference)}</h2>${o.mode==='test'?`<p class="commerce-box">${L('DEMO / TEST: NO REAL PAYMENT RECEIVED. Simulated subscriptions only; email delivery is disabled.','DÉMO / TEST : AUCUN PAIEMENT RÉEL REÇU. Abonnements simulés uniquement ; courriels désactivés.')}</p>`:''}<p data-order-main-status>${orderBadge(o)}</p><p>${e(o.customer.name)} · ${e(o.customer.email)}</p><p>${e(o.plan_name)} · ${e(F.formatDuration(o,locale))} · ${e(F.formatScreens(o.screens,locale))} · ${money(o.total_cents)} CAD</p><p>${L('Order Status','État de la commande')}: ${e(stateLabel(o.order_status))} · ${L('Payment Status','État du paiement')}: ${e(stateLabel(o.payment_status))} · ${e(o.created_at)}</p><h3>${L('Payment history','Historique des paiements')}</h3>${table([L('Method','Mode'),L('Reference','Référence'),L('Receiving account','Compte destinataire'),L('Expected amount','Montant attendu'),L('Status','État')],o.claims.map(c=>[e(c.method),e(c.confirmation),e(c.receiving_account?.nickname||L('Legacy account not recorded','Ancien compte non enregistré')),e(c.expected_amount||'')+' '+e(c.token||'CAD'),e(stateLabel(c.status))]))}<h3>${L('Invoices','Factures')}</h3>${o.invoices.map(invoiceLink).join(' ')}${o.payment_status==='paid'&&!o.invoices.some(i=>i.kind==='final'&&i.status!=='draft')?`<button class="btn" data-final-invoice>${L('Issue final invoice after billing verification','Émettre la facture définitive après vérification de facturation')}</button>`:''}<div data-subscription-delivery></div><details><summary>${L('Administrative notes','Notes administratives')}</summary><form data-notes><label class="field">${L('Administrative notes','Notes administratives')}<textarea name="notes" maxlength="4000">${e(o.notes)}</textarea></label><button class="btn">${L('Save notes','Enregistrer les notes')}</button></form></details>${o.payment_status!=='paid'?`<details><summary>${L('Update order status','Modifier l’état de la commande')}</summary><form data-order-state><label class="field">${L('Order status','État de la commande')}<select name="status">${['pending_payment','processing','cancelled','fulfilled','refunded'].map(s=>`<option value="${s}" ${['processing','cancelled'].includes(s)?'':'disabled'}>${e(stateLabel(s))}</option>`).join('')}</select></label><label class="field">${L('Cancellation reason','Motif d’annulation')}<textarea name="reason" maxlength="1000"></textarea></label>${o.mode==='test'&&o.payment_status==='paid'?`<label class="check-label"><input type="checkbox" name="testCancellation">${L('Confirm administrative test cancellation. Payment and invoice history will remain unchanged; no refund is sent.','Confirmer l’annulation administrative de test. L’historique des paiements et factures reste conservé ; aucun remboursement n’est envoyé.')}</label>`:''}<p data-order-state-error data-action-error role="status" aria-live="polite"></p><button class="btn">${L('Update status','Modifier l’état')}</button></form></details>`:''}<details data-activation-panel><summary>${L('Record subscription activation','Enregistrer l’activation')}</summary><h3>${o.mode==='test'?L('Simulated activation','Activation simulée'):L('Manual activation','Activation manuelle')}</h3><p>${o.mode==='test'?L('Record a simulated subscription only. Use a DEMO- reference; no provider account is created.','Enregistrez uniquement un abonnement simulé. Utilisez une référence DEMO- ; aucun compte fournisseur n’est créé.'):L('Activate only after actually provisioning the subscription. Do not put passwords in these notes.','Activez uniquement après avoir fourni l’abonnement. Ne placez aucun mot de passe dans ces notes.')}</p><form data-activate><label class="field">${L('Fulfillment reference','Référence d’activation')}<input name="fulfillmentReference" required minlength="3" ${o.mode==='test'?'placeholder="DEMO-activation-reference"':''}></label><button class="btn primary">${L('Record activation','Enregistrer l’activation')}</button></form></details><details><summary>${L('Credits and refunds','Crédits et remboursements')}</summary><h3>${L('Credit note after refund','Note de crédit après remboursement')}</h3><form data-credit><label class="field">${L('Reason','Motif')}<input name="reason" required minlength="3"></label><label class="field">${L('Verified refund reference','Référence du remboursement vérifié')}<input name="refundReference" required minlength="3"></label><button class="btn">${L('Record full refund and credit note','Enregistrer le remboursement complet et la note de crédit')}</button></form></details><details><summary>${L('Subscriptions','Abonnements')}</summary><h3>${L('Subscriptions','Abonnements')}</h3><pre>${e(JSON.stringify(o.subscriptions,null,2))}</pre></details><details><summary>${L('Verification history and quote details','Historique de vérification et devis')}</summary><pre>${e(JSON.stringify({history:o.verificationHistory,quotes:o.quotes},null,2))}</pre></details></div>`;
  $('[data-final-invoice]')?.addEventListener('click',safeAction(async()=>{await api('orders/'+id+'/final-invoice',{});await detail(id);message(L('Final invoice issued','Facture définitive émise'));}));
  await window.LuminaDeliveryAdmin({root:$('[data-subscription-delivery]'),order:o,api,L,e,onUpdate:()=>detail(id),onActivate:()=>{const form=$('[data-activate]');const panel=form?.closest('details');if(panel)panel.open=true;form?.scrollIntoView({behavior:'smooth',block:'center'});form?.elements.fulfillmentReference.focus();},message});
  const stateForm=o.payment_status==='paid'?null:$('[data-order-state]');if(stateForm){stateForm.elements.status.value=o.order_status;
  stateForm.addEventListener('submit',safeAction(async event=>{const data=Object.fromEntries(new FormData(event.target));data.testCancellation=event.target.elements.testCancellation?.checked===true;if(data.status===o.order_status){message(L('Status unchanged','État inchangé'));return;}await api('orders/'+id+'/status',data);await detail(id);message(L('Status saved. Order and dashboard data will reflect the saved state.','État enregistré. Les données de la commande et du tableau de bord sont actualisées.'));}));}
  for(const [selector,action]of [['[data-notes]','notes'],['[data-activate]','activate'],['[data-credit]','credit']])$(selector).addEventListener('submit',safeAction(async event=>{await api('orders/'+id+'/'+action,Object.fromEntries(new FormData(event.target)),{'Idempotency-Key':event.target.dataset.key||(event.target.dataset.key=crypto.randomUUID()+crypto.randomUUID())});await detail(id);message(L('Saved','Enregistré'));}));
 }
 function reviewForm(c){return `<form data-review="${e(c.id)}" class="commerce-box"><p data-action-error role="status" aria-live="polite"></p><h3>${e(c.plan_name)} · ${money(c.total_cents)} CAD · ${e(stateLabel(c.mode))}</h3><p>${e(c.order_reference||'')} · ${e(c.customer_name||'')} · ${e(c.customer_email||'')}</p><p>${e(c.method)} · ${e(c.confirmation)}</p><p>${e(c.receiving_account?.nickname||L('Legacy account not recorded','Ancien compte non enregistré'))} · ${e(c.receiving_account?.email||(c.receiving_account?.address?c.receiving_account.address.slice(0,8)+'…'+c.receiving_account.address.slice(-6):''))}</p><p>${e(c.token||'CAD')} / ${e(c.network||'Interac')} · ${e(c.address?c.address.slice(0,8)+'…'+c.address.slice(-6):'')} · ${e(c.quoted_amount)}</p>${c.receiving_account?.tokenContract?`<p>${L('Token contract','Contrat du jeton')}: ${e(c.receiving_account.tokenContract)}</p>`:''}<p>${L(c.mode==='test'?'DEMO: simulate the checks below. No money was received.':'Verify the bank or blockchain independently. Customer statements and screenshots alone are not receipt verification.','Vérifiez les critères ci-dessous ; en mode démo, aucune somme réelle n’est reçue.')}</p>${(c.method==='crypto'?['received','recipient','amount','token','network','success','finality']:['received','recipient','amount']).map(k=>`<label class="check-label"><input type="checkbox" name="${k}">${c.mode==='test'?L('Simulate: ','Simuler : '):''}${e(({received:L('Actual receipt verified','Réception réelle vérifiée'),recipient:L('Receiving account/address verified','Compte ou adresse destinataire vérifié'),amount:L('Correct amount and currency','Montant et devise corrects'),token:L('Correct token contract','Contrat du jeton correct'),network:L('Correct network','Réseau correct'),success:L('Transaction succeeded','Transaction réussie'),finality:L('Required finality confirmed','Finalité requise confirmée')})[k])}</label>`).join('')}<label class="field">${L('Independent bank or explorer reference','Référence indépendante bancaire ou d’explorateur')}<input name="verificationReference" maxlength="300" ${c.mode==='test'?'placeholder="DEMO-verification-reference"':''}></label><label class="field">${L('Review notes / rejection reason','Notes ou motif de rejet')}<textarea name="notes" maxlength="2000"></textarea></label><div class="actions"><button class="btn primary" name="action" value="approve">${c.mode==='test'?L('Approve simulated payment','Approuver le paiement simulé'):L('Confirm verified payment','Confirmer le paiement vérifié')}</button><button class="btn" name="action" value="reject">${L('Reject payment claim','Rejeter la déclaration')}</button></div></form>`;}
 async function load(){const route=location.pathname.replace(/^\/fr/,'').split('/')[2]||'dashboard';status.textContent='';
 if(route==='dashboard'){const d=await api('dashboard?mode=live'),prefix=fr?'/fr':'',cards=[[L('Total orders','Commandes totales'),d.total_orders,'/admin/orders/?mode=live'],[L('Pending orders','Commandes en attente'),d.pending_orders,'/admin/orders/?status=pending_payment&mode=live'],[L('Paid orders','Commandes payées'),d.paid_orders,'/admin/orders/?status=paid&mode=live'],[L('Verified revenue','Revenus vérifiés'),money(d.revenue_cents),'/admin/orders/?status=paid&mode=live'],[L('Payments to review','Paiements à vérifier'),d.awaiting_verification,'/admin/payments/?status=pending&mode=live'],[L('Active subscriptions','Abonnements actifs'),d.subscriptions.find(s=>s.status==='active')?.count||0,'/admin/subscriptions/?status=active']];content.innerHTML=`<div class="dashboard-intro"><p>${L('Your business at a glance.','Votre activité en un coup d’œil.')}</p><a class="btn primary" href="${prefix}/admin/orders/">${L('Manage orders','Gérer les commandes')} <span aria-hidden="true">↗</span></a></div><div class="admin-metrics">${cards.map(([label,value,href],i)=>`<a class="admin-stat ${i===3?'admin-stat-revenue':''}" href="${prefix+href}"><span>${label}</span><strong>${e(value??0)}</strong><small>${i===3?L('Verified payments · CAD','Paiements vérifiés · CAD'):L('View records','Voir les données')} <span aria-hidden="true">↗</span></small></a>`).join('')}</div><div class="dashboard-workspace"><section class="dashboard-panel dashboard-orders"><header><h2>${L('Recent orders','Commandes récentes')}</h2><a href="${prefix}/admin/orders/">${L('View all','Tout voir')} ↗</a></header>${d.recentOrders.length?table([L('Order','Commande'),L('Plan','Forfait'),L('Status','État'),L('Payment','Paiement'),'CAD'],d.recentOrders.map(o=>[orderLink(o),e(o.plan_name),orderBadge(o),e(stateLabel(o.payment_status)),money(o.total_cents)])):'<p class="dashboard-empty">'+L('Your orders will appear here.','Vos commandes apparaîtront ici.')+'</p>'}</section><section class="dashboard-panel dashboard-attention"><header><h2>${L('Needs attention','À vérifier')}</h2><span class="admin-badge state-pending">${d.awaiting_verification||0}</span></header>${d.attention?.length?d.attention.map(c=>`<a class="attention-item" href="${prefix}/admin/payments/?status=pending"><span class="attention-avatar" aria-hidden="true">${e(c.customer_name?.charAt(0)||'?')}</span><span><strong>${e(c.customer_name)}</strong><small>${e(c.plan_name)} · ${money(c.total_cents)}</small></span><span aria-hidden="true">↗</span></a>`).join(''):'<div class="dashboard-empty"><strong>'+L('You’re all caught up','Tout est à jour')+'</strong><p>'+L('No payments awaiting review.','Aucun paiement à vérifier.')+'</p></div>'}<a class="attention-all" href="${prefix}/admin/payments/?status=pending">${L('Open payments','Voir les paiements')} →</a></section></div>`;wireOrders();return;}
 if(route==='payment-accounts'){await window.LuminaPaymentAccounts({root:content,api,L,e,message});return;}
 if(route==='settings'){await window.LuminaSettings({root:content,api,L,e,message});return;}
 const params=new URLSearchParams(location.search),revenue=route==='orders'&&params.get('status')==='paid'?await api('revenue?mode=live'):null;
 await window.LuminaAdminData({revenue,root:content,kind:route,api,L,e,money,stateLabel,orderLink,invoiceLink,onRows:()=>{wireOrders();content.querySelectorAll('[data-send-invoice]').forEach(b=>b.addEventListener('click',safeAction(async()=>{await api('invoices/'+b.dataset.sendInvoice+'/email',{});message(L('Email sent','Courriel envoyé'));})));},onReview:(record,area)=>{area.innerHTML=reviewForm(record);area.querySelector('form').addEventListener('submit',safeAction(async event=>{const fd=new FormData(event.target),checks=Object.fromEntries(['received','recipient','amount','token','network','success','finality'].map(k=>[k,fd.get(k)==='on']));await api('claims/'+record.id+'/review',{action:event.submitter.value,verificationReference:fd.get('verificationReference'),notes:fd.get('notes'),checks});await load();}));area.scrollIntoView({behavior:'smooth',block:'start'});}});

 }
 function setupSidebar(){const nav=shell.querySelector('.admin-nav'),logout=nav.querySelector('[data-logout]'),prefix=fr?'/fr':'',route=location.pathname.replace(/^\/fr/,'').split('/')[2]||'dashboard';
 const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',orders:'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4',payments:'M3 5h18v14H3z M3 9h18 M7 15h3','payment-accounts':'M3 7h18v14H3z M6 7V3h12v4 M16 12h5',invoices:'M6 2h9l4 4v16H6z M9 11h7 M9 15h7',customers:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8a4 4 0 0 0 0-8 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-4',subscriptions:'M4 7h16v13H4z M8 3v8 M16 3v8 M4 12h16',settings:'M12 8a4 4 0 1 0 0 8a4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
 const icon=name=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+paths[name]+'"/></svg>';
 const groups=[[L('Overview','Vue d’ensemble'),[['dashboard',L('Dashboard','Tableau de bord')]]],[L('Sales','Ventes'),[['orders',L('Orders','Commandes')],['payments',L('Payments','Paiements')],['invoices',L('Invoices','Factures')]]],[L('Management','Gestion'),[['payment-accounts',L('Payment accounts','Comptes de paiement')],['customers',L('Customers','Clients')],['subscriptions',L('Subscriptions','Abonnements')]]],[L('System','Système'),[['settings',L('Settings','Paramètres')]]]];
 nav.innerHTML='<div class="admin-nav-top"><a class="admin-brand" href="'+prefix+'/admin/"><span class="admin-brand-icon">L</span><span class="nav-label">Lumina Stream<small>Administration</small></span></a><button type="button" class="admin-collapse" aria-label="'+L('Collapse sidebar','Réduire le menu')+'" title="'+L('Collapse sidebar','Réduire le menu')+'">‹</button></div>'+groups.map(([label,links])=>'<div class="admin-nav-group"><span class="nav-group-label">'+label+'</span>'+links.map(([key,text])=>'<a href="'+prefix+'/admin/'+(key==='dashboard'?'':key+'/')+'" title="'+text+'" '+(key===route?'aria-current="page"':'')+'>'+icon(key)+'<span class="nav-label">'+text+'</span></a>').join('')+'</div>').join('')+'<footer class="admin-nav-footer"><div class="admin-account"><span class="admin-avatar">A</span><span class="nav-label">'+L('Administrator','Administrateur')+'<small>'+e(shell.dataset.actor||'')+'</small></span></div><div class="admin-preferences"></div></footer>';
 nav.id='admin-sidebar';nav.setAttribute('aria-label',L('Administration navigation','Navigation administrative'));const footer=nav.querySelector('.admin-nav-footer');if(logout){logout.title=L('Sign out','Se déconnecter');footer.append(logout);}const preferences=nav.querySelector('.admin-preferences');for(const control of document.querySelectorAll('.site-header .theme-toggle,.site-header .language-toggle'))preferences.append(control);
 let compact=false;try{compact=localStorage.getItem('lumina:admin-sidebar')==='compact';}catch{}const apply=()=>{document.body.classList.toggle('admin-compact',compact);nav.querySelector('.admin-collapse').setAttribute('aria-expanded',String(!compact));};apply();nav.querySelector('.admin-collapse').onclick=()=>{compact=!compact;apply();try{localStorage.setItem('lumina:admin-sidebar',compact?'compact':'expanded');}catch{}};
 if(!shell.querySelector('.admin-sidebar-toggle')){const toggle=document.createElement('button');toggle.type='button';toggle.className='admin-sidebar-toggle';toggle.setAttribute('aria-controls','admin-sidebar');toggle.setAttribute('aria-expanded','false');toggle.textContent='☰ '+L('Menu','Menu');toggle.onclick=()=>{const open=document.body.classList.toggle('admin-sidebar-open');toggle.setAttribute('aria-expanded',String(open));nav.inert=!open;if(open)nav.querySelector('a')?.focus();};shell.prepend(toggle);}const drawerMedia=matchMedia('(max-width:1024px)'),syncDrawer=()=>{nav.inert=drawerMedia.matches&&!document.body.classList.contains('admin-sidebar-open');};syncDrawer();drawerMedia.addEventListener('change',syncDrawer);const titles={dashboard:L('Overview','Vue d’ensemble'),orders:L('Orders','Commandes'),payments:L('Payments','Paiements'),invoices:L('Invoices','Factures'),customers:L('Customers','Clients'),subscriptions:L('Subscriptions','Abonnements'),'payment-accounts':L('Payment accounts','Comptes de paiement'),settings:L('Settings','Paramètres')};shell.querySelector('h1').textContent=titles[route]||'Administration';
 }
 function closeSidebar(){document.body.classList.remove('admin-sidebar-open');const nav=shell.querySelector('.admin-nav');if(nav)nav.inert=matchMedia('(max-width:1024px)').matches;shell.querySelector('.admin-sidebar-toggle')?.setAttribute('aria-expanded','false');}
 document.addEventListener('keydown',event=>{if(event.key==='Escape')closeSidebar();});document.addEventListener('click',event=>{if(document.body.classList.contains('admin-sidebar-open')&&!event.target.closest('.admin-nav,.admin-sidebar-toggle'))closeSidebar();});
 async function signedIn(){const s=await api('session');csrf=s.csrf;shell.dataset.actor=s.actor;document.body.classList.add('admin-authenticated');$('[data-admin-login]').hidden=true;$('[data-admin-app]').hidden=false;if(!$('[data-logout]')){const logout=document.createElement('button');logout.className='btn small';logout.dataset.logout='';logout.textContent=L('Sign out','Se déconnecter');logout.addEventListener('click',safeAction(async()=>{if(s.authMode!=='sites'){await api('logout',{});location.reload();return;}location.href=fr?'/signout-with-chatgpt?return_to=%2Ffr%2Fadmin%2F':'/signout-with-chatgpt?return_to=%2Fadmin%2F';}));shell.querySelector('.admin-nav').append(logout);}setupSidebar();await load();}
 $('[data-admin-login-form]').addEventListener('submit',safeAction(async event=>{const s=await api('login',Object.fromEntries(new FormData(event.target)));csrf=s.csrf;event.target.reset();await signedIn();}));signedIn().catch(()=>{});
})();
